mapper.select:
/* CatMngSQL.selectCatMngList */ SELECT CAT_CD AS "catCd", CAT_NM AS "catNm", UP_CAT_CD AS "upCatCd", CAT_LVL AS "catLvl", SORT_SEQ AS "sortSeq", USE_YN AS "useYn" FROM TB_CAT_MNG WHERE CAT_LVL = #{catLvl}
AND UP_CAT_CD = #{upCatCd}
ORDER BY SORT_SEQ, CAT_CD

/* CatMngSQL.selectMaxCatCd */
SELECT MAX(CAT_CD)
FROM TB_CAT_MNG
WHERE CAT_LVL = #{catLvl}

mapper.insert:
/* CatMngSQL.insertCat */
INSERT INTO TB_CAT_MNG (
	CAT_CD, CAT_NM, UP_CAT_CD, CAT_LVL, SORT_SEQ, USE_YN
) VALUES (
	#{catCd}, #{catNm}, #{upCatCd}, #{catLvl}, #{sortSeq}, #{useYn}
)

mapper.update:
/* CatMngSQL.updateCat */
UPDATE TB_CAT_MNG
SET CAT_NM = #{catNm},
	SORT_SEQ = #{sortSeq},
	USE_YN = #{useYn}
WHERE CAT_CD = #{catCd}

mapper.delete:
/* CatMngSQL.deleteCat */
DELETE FROM TB_CAT_MNG
WHERE CAT_CD = #{catCd}

mapper.select:
/* CatMngSQL.selectSubCatCnt */
SELECT COUNT(*)
FROM TB_CAT_MNG
WHERE UP_CAT_CD = #{catCd}

/* CatMngSQL.selectCatPrdCnt */
SELECT COUNT(*)
FROM TB_PRD_MST
WHERE

	L_CAT_CD = #{catCd}
	M_CAT_CD = #{catCd}
	S_CAT_CD = #{catCd}
